CSS_D:
@page{size:297mm 210mm;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0}
body{-webkit-print-color-adjust:exact;print-color-adjust:exact}
.pg{width:297mm;height:210mm;position:relative;overflow:hidden;page-break-after:always;break-after:page}
.pg:last-child{page-break-after:auto;break-after:auto}
figure{margin:0}img{display:block;width:100%}
table.dt{width:100%;border-collapse:collapse;table-layout:fixed}
table.dt td,table.dt th{vertical-align:top;text-align:left;word-wrap:break-word;overflow-wrap:anywhere}
td.mono,.mono{font-family:'IBM Plex Mono',monospace}
.two{display:grid;grid-template-columns:1fr 1fr;gap:7mm}.two p{margin:0 0 1.2mm}
.foot .pn{float:right}
h1,h2,.stats b,p.big,p.brand{font-variant-numeric:lining-nums}
table.dt th{overflow-wrap:normal;word-break:normal;letter-spacing:.2pt!important}
.p2 p.b{font-size:12pt!important;line-height:1.5}.p2 p.src{font-size:8pt}.p2 h2.h2{font-size:17pt;margin-top:5mm}
.p14 p.b{font-size:10.6pt}
.covlow p{margin:0 0 1.1mm}.covlow p.brand{margin-bottom:1.5mm!important}
.thin{height:.7px;background:#d9d9d9;margin:3mm 0 2.5mm}

.pg{background:#FFFFFF;color:#111;font-family:'Manrope','Inter',sans-serif;display:flex}
.side{position:absolute;left:0;top:0;bottom:0;width:56mm;background:#07080A;color:#E8EAED;padding:9mm 6.5mm 8mm;overflow:hidden}
.content{position:absolute;left:66mm;right:10mm;top:9mm;bottom:15mm;overflow:hidden}
.lab{font-family:'Inter';font-size:6.3pt;letter-spacing:1.5pt;color:#D4A84B;font-weight:800;text-transform:uppercase;display:block}
.k{margin-top:3.4mm}.k b{display:block;font-family:'Sora';font-size:14pt;font-weight:700;color:#5CCFE0;line-height:1.15;margin-top:.4mm}
.k b.r{color:#E5534B}.k b.w{color:#E8EAED}.k b.s{font-size:10pt}
.sdiv{height:1px;background:#1E232B;margin:4.2mm 0 0}
.sec{font-family:'Inter';font-size:6.3pt;letter-spacing:1.5pt;color:#8A919C;text-transform:uppercase;font-weight:700;margin-top:4mm}
.kick{font-family:'Inter';font-size:7pt;letter-spacing:1.6pt;color:#9A7420;font-weight:800;text-transform:uppercase;margin-bottom:1.5mm}
h1.h1,h1.hl{font-family:'Sora';font-weight:700;font-size:21pt;letter-spacing:-.4pt;line-height:1.12;margin:0 0 2.6mm;color:#0c0d10}
h2.h2{font-family:'Sora';font-weight:700;font-size:13.5pt;letter-spacing:-.2pt;line-height:1.2;margin:3mm 0 1.6mm;color:#0c0d10}
.content>h2.h2:first-of-type{margin-top:0}
p.b{font-size:9.7pt;line-height:1.5;margin:0 0 1.5mm;color:#333}
p.b.sm{font-size:8.9pt;line-height:1.45}
p.src{font-family:'Inter';font-size:7.2pt;line-height:1.35;color:#8a8a8a;margin:.6mm 0 2.3mm}
p.big{font-family:'Sora';font-weight:700;font-size:14pt;margin:4mm 0 0;border:1px solid #f1c9c5;background:#FDF1F0;border-radius:3mm;padding:3mm 4mm}
.n{color:#127485;font-weight:700}.r{color:#C0352B;font-weight:700}.g{color:#9A7420;font-weight:700}.m{color:#8A8A8A}
figure.frame img,figure.graph img,figure.cframe img{border-radius:2.6mm}
figure.frame{width:214mm;margin:1.5mm 0 4mm}
figure.graph{width:221mm;margin:1mm 0 3.5mm}
table.dt{font-family:'IBM Plex Sans Condensed';font-size:7.1pt;line-height:1.27;margin:1mm 0 2mm;border:1px solid #e3e3e3}
table.dt th{font-family:'Inter';font-size:6.4pt;letter-spacing:.5pt;text-transform:uppercase;color:#9A7420;font-weight:800;padding:1.5mm 1.3mm;background:#F6F6F4;border-bottom:1px solid #e3e3e3}
table.dt td{padding:1mm 1.3mm;border-bottom:.6px solid #ececec;color:#1d1f23}
table.dt tbody tr:nth-child(even) td{background:#FAFAFA}
table.dt td.mono{font-size:6.4pt;line-height:1.3;color:#3a3d42}
.two p.b{font-size:9.2pt}
.foot{position:absolute;left:66mm;right:10mm;bottom:6.5mm;font-family:'Inter';font-size:6.7pt;color:#888;border-top:1px solid #eee;padding-top:1.8mm}
.tag{display:inline-block;background:#FDECEC;color:#B23A32;font-family:'Inter';font-weight:800;font-size:7.5pt;padding:1.2mm 3mm;border-radius:5mm;margin:0 1.5mm 2.5mm 0}
.tag.g{background:#EEF6F8;color:#167a8a}
.cov{display:grid;grid-template-columns:150mm 1fr;gap:6mm;align-items:start;margin:1mm 0 3mm}
.cvt{display:flex;align-items:center;flex-wrap:wrap;margin-bottom:2mm}.cvt .tag{margin-bottom:0}
.box{border:1px solid #e5e5e5;border-radius:3mm;padding:3mm 4mm;margin-top:2mm}
p.brand{font-family:'Sora';font-weight:700;font-size:11.5pt;margin:0 0 1mm!important;line-height:1.25}
p.cbig{font-size:9.3pt;font-weight:700;line-height:1.38}
p.cak{font-family:'IBM Plex Mono';font-size:8.2pt;line-height:1.35}
.covlow p.b{font-size:8.9pt;line-height:1.42}
